import{_ as e,c as r,o as n,a0 as t}from"./chunks/framework.DKRgXLPU.js";const i=JSON.parse('{"title":"Introduktion til mentalt spil - slides til facilitator","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/da/facilitator-slides.md","filePath":"public/downloads/da/facilitator-slides.md"}');const a=e({name:"public/downloads/da/facilitator-slides.md"},[["render",function(e,i,a,l,s,d){return n(),r("div",null,[...i[0]||(i[0]=[t('<h1 id="introduktion-til-mentalt-spil-slides-til-facilitator" tabindex="-1">Introduktion til mentalt spil - slides til facilitator <a class="header-anchor" href="#introduktion-til-mentalt-spil-slides-til-facilitator" aria-label="Permalink to &quot;Introduktion til mentalt spil - slides til facilitator&quot;">​</a></h1><p><strong>Petanque Akademi</strong><em>Sessionsguide for facilitatorer</em></p><hr><h2 id="slide-1-velkommen" tabindex="-1">Slide 1: Velkommen <a class="header-anchor" href="#slide-1-velkommen" aria-label="Permalink to &quot;Slide 1: Velkommen&quot;">​</a></h2><h1 id="🎯-introduktion-til-mentalt-spil" tabindex="-1">🎯 Introduktion til mentalt spil <a class="header-anchor" href="#🎯-introduktion-til-mentalt-spil" aria-label="Permalink to &quot;🎯 Introduktion til mentalt spil&quot;">​</a></h1><p><strong>For Elite Petanque-spillere</strong></p><h3 id="i-dag-vil-du-opdage" tabindex="-1">I dag vil du opdage: <a class="header-anchor" href="#i-dag-vil-du-opdage" aria-label="Permalink to &quot;I dag vil du opdage:&quot;">​</a></h3><ul><li>🧠 Sådan skaber du de rette betingelser for &quot;zonen&quot;</li><li>💪 Sådan dæmper du din indre kritiker</li><li>🎪 Praktiske værktøjer, der fungerer under pres</li></ul><p><strong>Gør dig klar til en interaktiv session!</strong></p><hr><h2 id="slide-2-hurtig-afstemning-ræk-handen-op-🙋" tabindex="-1">Slide 2: Hurtig afstemning - Ræk hånden op! 🙋 <a class="header-anchor" href="#slide-2-hurtig-afstemning-ræk-handen-op-🙋" aria-label="Permalink to &quot;Slide 2: Hurtig afstemning - Ræk hånden op! 🙋&quot;">​</a></h2><h3 id="hvem-har-oplevet-dette" tabindex="-1">Hvem har oplevet dette? <a class="header-anchor" href="#hvem-har-oplevet-dette" aria-label="Permalink to &quot;Hvem har oplevet dette?&quot;">​</a></h3><p><strong>Ræk hånden op, hvis du nogensinde har:</strong></p><ol><li><p>Lavede du et perfekt skud i træningen... og så missede du det i konkurrencen? 🎯❌</p></li><li><p>Følte du, at dine tanker løb rundt, da du havde brug for at bevare roen? 🧠💨</p></li><li><p>Kritiserede du dig selv efter en fejl? 😤</p></li><li><p>Har du haft et spil, hvor alt bare &quot;klikkede&quot;? ✨</p></li></ol><p><strong>Du er ikke alene! Lad os løse dette sammen.</strong></p><hr><h2 id="slide-3-elitespillerparadokset" tabindex="-1">Slide 3: Elitespillerparadokset <a class="header-anchor" href="#slide-3-elitespillerparadokset" aria-label="Permalink to &quot;Slide 3: Elitespillerparadokset&quot;">​</a></h2><h3 id="du-har-allerede-færdighederne-sa-hvorfor" tabindex="-1">Du har allerede færdighederne ... så hvorfor? <a class="header-anchor" href="#du-har-allerede-færdighederne-sa-hvorfor" aria-label="Permalink to &quot;Du har allerede færdighederne ... så hvorfor?&quot;">​</a></h3><p><strong>✅ Du HAR:</strong></p><ul><li>Fremragende teknik (tusindvis af timer)</li><li>Årelang erfaring</li><li>Fysisk evne</li></ul><p><strong>❌ Men du KÆMPER med:</strong></p><ul><li>Adgang til den teknik under pres</li><li>At forblive konsekvent i konkurrencen</li><li>Kom tilbage efter fejltagelser</li></ul><h3 id="den-manglende-brik-🧩" tabindex="-1">Den manglende brik? 🧩 <a class="header-anchor" href="#den-manglende-brik-🧩" aria-label="Permalink to &quot;Den manglende brik? 🧩&quot;">​</a></h3><p><strong>Dit mentale spil.</strong></p><p><em>&quot;Forskellen på godt og fantastisk er, hvad der sker mellem dine ører.&quot;</em></p><hr><h2 id="slide-4-zonen-du-kender-den-følelse-⚡" tabindex="-1">Slide 4: Zonen - Du kender den følelse! ⚡ <a class="header-anchor" href="#slide-4-zonen-du-kender-den-følelse-⚡" aria-label="Permalink to &quot;Slide 4: Zonen - Du kender den følelse! ⚡&quot;">​</a></h2><h3 id="husker-du-det-perfekte-spil" tabindex="-1">Husker du det perfekte spil? <a class="header-anchor" href="#husker-du-det-perfekte-spil" aria-label="Permalink to &quot;Husker du det perfekte spil?&quot;">​</a></h3><p><strong>Alt føltes:</strong></p><ul><li>⏱️ Tiden gik langsommere</li><li>🎯 Ubesværet og automatisk</li><li>🧘 Fuldstændig fokuseret</li><li>🎪 Som om du ikke kunne gå glip af det</li></ul><h3 id="det-er-quot-zonen-quot-flowtilstand" tabindex="-1">Det er &quot;Zonen&quot; (Flowtilstand) <a class="header-anchor" href="#det-er-quot-zonen-quot-flowtilstand" aria-label="Permalink to &quot;Det er &amp;quot;Zonen&amp;quot; (Flowtilstand)&quot;">​</a></h3><p><strong>Spørgsmålet:</strong><em>Hvordan får vi adgang til det konsekvent, ikke bare ved et uheld?</em></p><p><strong>Svaret:</strong><em>Forstå dine to tankemåder...</em></p><hr><h2 id="slide-5-din-hjerne-har-to-tilstande-🧠" tabindex="-1">Slide 5: Din hjerne har to tilstande 🧠 <a class="header-anchor" href="#slide-5-din-hjerne-har-to-tilstande-🧠" aria-label="Permalink to &quot;Slide 5: Din hjerne har to tilstande 🧠&quot;">​</a></h2><h3 id="🤔-planlægningstilstand-analytisk-hjerne" tabindex="-1">🤔 PLANLÆGNINGSTILSTAND (Analytisk hjerne) <a class="header-anchor" href="#🤔-planlægningstilstand-analytisk-hjerne" aria-label="Permalink to &quot;🤔 PLANLÆGNINGSTILSTAND (Analytisk hjerne)&quot;">​</a></h3><p><strong>Hvornår skal det bruges:</strong> FØR indsprøjtningen</p><ul><li>📊 Analyse af terrænet</li><li>🎯 Valg af din strategi</li><li>⚖️ Afvejning af risici</li><li>🤝 Beslutter skuddet</li></ul><h3 id="🎯-udførelsestilstand-flow-brain" tabindex="-1">🎯 UDFØRELSESTILSTAND (Flow Brain) <a class="header-anchor" href="#🎯-udførelsestilstand-flow-brain" aria-label="Permalink to &quot;🎯 UDFØRELSESTILSTAND (Flow Brain)&quot;">​</a></h3><p><strong>Hvornår skal det bruges:</strong> UNDER indsprøjtningen</p><ul><li>💪 Stol på din krop</li><li>🚫 Tænker IKKE på teknik</li><li>⏰ Kun nuet</li><li>🤖 Automatisk ydeevne</li></ul><h3 id="⚠️-problemet" tabindex="-1">⚠️ PROBLEMET: <a class="header-anchor" href="#⚠️-problemet" aria-label="Permalink to &quot;⚠️ PROBLEMET:&quot;">​</a></h3><p><strong>De fleste spillere forbliver i planlægningstilstand under udførelsen!</strong><em>Din analytiske hjerne forstyrrer din automatiske præstation.</em></p><hr><h2 id="slide-6-kontakten-dit-hemmelige-vaben-🔄" tabindex="-1">Slide 6: Kontakten - Dit hemmelige våben 🔄 <a class="header-anchor" href="#slide-6-kontakten-dit-hemmelige-vaben-🔄" aria-label="Permalink to &quot;Slide 6: Kontakten - Dit hemmelige våben 🔄&quot;">​</a></h2><h3 id="mestre-denne-ene-færdighed" tabindex="-1">Mestre denne ene færdighed: <a class="header-anchor" href="#mestre-denne-ene-færdighed" aria-label="Permalink to &quot;Mestre denne ene færdighed:&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BEFORE the shot:          DURING the shot:</span></span>\n<span class="line"><span>🤔 Planning Mode    →     🎯 Execution Mode</span></span></code></pre></div><h3 id="processen" tabindex="-1">Processen: <a class="header-anchor" href="#processen" aria-label="Permalink to &quot;Processen:&quot;">​</a></h3><p><strong>1️⃣ FØR (10-15 sekunder):</strong></p><ul><li>🤔 Analyser alt</li><li>📊 Planlæg din strategi</li><li>✅ Træf din beslutning</li></ul><p><strong>2️⃣ SKIFTEN (3 åndedrag):</strong></p><ul><li>🌬️ Træk vejret dybt</li><li>🧘 Ryd op i tankerne</li><li>🔄 Slip analysen</li></ul><p><strong>3️⃣ I LØBET AF (2-3 sekunder):</strong></p><ul><li>🎯 Stol fuldt ud på</li><li>🤖 Lad det ske</li><li>⚡ Udfør automatisk</li></ul><p><strong>Øv denne switch = Adgangsflow efter behov!</strong></p><hr><h2 id="slide-7-aktivitet-prøv-det-nu-🎯" tabindex="-1">Slide 7: AKTIVITET - Prøv det nu! 🎯 <a class="header-anchor" href="#slide-7-aktivitet-prøv-det-nu-🎯" aria-label="Permalink to &quot;Slide 7: AKTIVITET - Prøv det nu! 🎯&quot;">​</a></h2><h3 id="lad-os-øve-os-pa-at-skifte-2-minutter" tabindex="-1">Lad os øve os på at skifte (2 minutter) <a class="header-anchor" href="#lad-os-øve-os-pa-at-skifte-2-minutter" aria-label="Permalink to &quot;Lad os øve os på at skifte (2 minutter)&quot;">​</a></h3><p><strong>Alle sammen, stå op!</strong></p><ol><li><p><strong>Planlægningstilstand (10 sek.):</strong> Forestil dig at analysere et skud. Tænk på terræn, strategi og risici.</p></li><li><p><strong>Switchen (3 åndedrag):</strong> Tag 3 dybe indåndinger. Ryd dine tanker med hver udånding.</p></li><li><p><strong>Udførelsestilstand (3 sek.):</strong> Forestil dig at kaste. Ingen tænkning. Bare tillid og flow.</p></li></ol><p><strong>Hvordan føltes det? Anderledes?</strong></p><p><em>Sæt jer ned, og lad os snakke...</em></p><hr><h2 id="slide-8-mød-din-indre-kritiker-😈" tabindex="-1">Slide 8: Mød din indre kritiker 😈 <a class="header-anchor" href="#slide-8-mød-din-indre-kritiker-😈" aria-label="Permalink to &quot;Slide 8: Mød din indre kritiker 😈&quot;">​</a></h2><h3 id="lyder-denne-stemme-bekendt" tabindex="-1">Lyder denne stemme bekendt? <a class="header-anchor" href="#lyder-denne-stemme-bekendt" aria-label="Permalink to &quot;Lyder denne stemme bekendt?&quot;">​</a></h3><p><strong>Efter et dårligt skud:</strong></p><ul><li>💢 &quot;Det var FORFÆRDELIGT!&quot;</li><li>😤 &quot;Du laver ALTID fejl under pres!&quot;</li><li>😰 &quot;Alle ser dig fejle!&quot;</li><li>😞 &quot;Du er bare ikke god nok!&quot;</li></ul><h3 id="hurtig-afstemning-🙋" tabindex="-1">Hurtig afstemning: 🙋 <a class="header-anchor" href="#hurtig-afstemning-🙋" aria-label="Permalink to &quot;Hurtig afstemning: 🙋&quot;">​</a></h3><p>Hvem hører denne stemme regelmæssigt?</p><h3 id="sandheden" tabindex="-1">Sandheden: <a class="header-anchor" href="#sandheden" aria-label="Permalink to &quot;Sandheden:&quot;">​</a></h3><p><strong>Din indre kritiker prøver at hjælpe...</strong><em>Men det ødelægger faktisk din præstation.</em></p><hr><h2 id="slide-9-fyr-din-kritiker-ansæt-din-coach-🔄" tabindex="-1">Slide 9: Fyr din kritiker, ansæt din coach! 🔄 <a class="header-anchor" href="#slide-9-fyr-din-kritiker-ansæt-din-coach-🔄" aria-label="Permalink to &quot;Slide 9: Fyr din kritiker, ansæt din coach! 🔄&quot;">​</a></h2><h3 id="transformationen" tabindex="-1">Transformationen: <a class="header-anchor" href="#transformationen" aria-label="Permalink to &quot;Transformationen:&quot;">​</a></h3><p>| 😈 Indre kritiker | ➡️ | 😊 Indre coach | |---------------| ... | &quot;Du laver ALTID fejl!&quot; | → | &quot;Jeg har taget dette billede 1000 gange før&quot; | | &quot;Det var FORFÆRDELIGT!&quot; | → | &quot;Hvad kan jeg lære af det her?&quot; | | &quot;Alle dømmer dig!&quot; | → | &quot;Fokuser på MIT spil, ikke deres meninger&quot; | | &quot;Du er ikke god nok!&quot; | → | &quot;Jeg bliver bedre hver dag&quot; |</p><h3 id="virkningen" tabindex="-1">Virkningen: <a class="header-anchor" href="#virkningen" aria-label="Permalink to &quot;Virkningen:&quot;">​</a></h3><p><strong>Kriticus = Angst, spænding, dårlig præstation</strong><strong>Træner = Selvtillid, afslapning, toppræstation</strong></p><hr><h2 id="slide-10-aktivitet-omformuler-din-kritiker-💬" tabindex="-1">Slide 10: AKTIVITET - Omformuler din kritiker! 💬 <a class="header-anchor" href="#slide-10-aktivitet-omformuler-din-kritiker-💬" aria-label="Permalink to &quot;Slide 10: AKTIVITET - Omformuler din kritiker! 💬&quot;">​</a></h2><h3 id="partnerøvelse-3-minutter" tabindex="-1">Partnerøvelse (3 minutter) <a class="header-anchor" href="#partnerøvelse-3-minutter" aria-label="Permalink to &quot;Partnerøvelse (3 minutter)&quot;">​</a></h3><p><strong>Vend dig mod personen ved siden af dig:</strong></p><p><strong>Person A (1,5 min):</strong></p><ol><li>Del én ting, din indre kritiker siger</li><li>Partner hjælper dig med at omformulere det som Indre Coach</li><li>Skriv den nye sætning ned</li></ol><p><strong>Person B (1,5 min):</strong></p><ol><li>Samme proces</li><li>Del dine tanker om den indre kritiker</li><li>Få hjælp til at omformulere det</li></ol><p><strong>Klar? Kom i gang!</strong></p><p><em>Vi deler et par eksempler med gruppen bagefter...</em></p><hr><h2 id="slide-11-værktøj-1-nulstilling-af-3-andedræt-🌬️" tabindex="-1">Slide 11: Værktøj #1 - Nulstilling af 3 åndedræt 🌬️ <a class="header-anchor" href="#slide-11-værktøj-1-nulstilling-af-3-andedræt-🌬️" aria-label="Permalink to &quot;Slide 11: Værktøj #1 - Nulstilling af 3 åndedræt 🌬️&quot;">​</a></h2><h3 id="din-nødtryksventil" tabindex="-1">Din nødtryksventil <a class="header-anchor" href="#din-nødtryksventil" aria-label="Permalink to &quot;Din nødtryksventil&quot;">​</a></h3><p><strong>Brug dette når:</strong></p><ul><li>😤 Du har lige lavet en fejl</li><li>😰 Du føler presset vokse</li><li>🤯 Dine tanker kører på løb</li></ul><h3 id="processen-1" tabindex="-1">Processen: <a class="header-anchor" href="#processen-1" aria-label="Permalink to &quot;Processen:&quot;">​</a></h3><p><strong>🌬️ INDÅNDING 1 (Indånd 4 sek.):</strong> Læg mærke til, hvor du føler spænding (skuldre? kæbe? mave?)</p><p><strong>🌬️ 2 ÅNDEDRÆT (Udånd i 6 sekunder):</strong> Slip spændingen. Lad den flyde ud med dit åndedræt.</p><p><strong>🌬️ ÅNDTRÆK 3 (Indånd 4, Udånd 6):</strong> Fokuser på NU. Dette billede. Dette øjeblik. Intet andet.</p><p><strong>⏱️ Tager 20 sekunder. Ændrer alt.</strong></p><hr><h2 id="slide-12-demo-prøv-det-alle-sammen-🌬️" tabindex="-1">Slide 12: DEMO - Prøv det alle sammen! 🌬️ <a class="header-anchor" href="#slide-12-demo-prøv-det-alle-sammen-🌬️" aria-label="Permalink to &quot;Slide 12: DEMO - Prøv det alle sammen! 🌬️&quot;">​</a></h2><h3 id="_3-andedrætsnulstillingsøvelse-1-minut" tabindex="-1">3-åndedrætsnulstillingsøvelse (1 minut) <a class="header-anchor" href="#_3-andedrætsnulstillingsøvelse-1-minut" aria-label="Permalink to &quot;3-åndedrætsnulstillingsøvelse (1 minut)&quot;">​</a></h3><p><strong>Alle sammen lukker øjnene...</strong></p><p><strong>Åndedræt 1:</strong><em>Træk vejret ind i 4 sekunder... Hvor føler du spænding?</em></p><p><strong>Åndedræt 2:</strong><em>Påvirkning i 6 sekunder... Lad det gå...</em></p><p><strong>Åndedræt 3:</strong><em>Ind for 4, ud for 6... Kun i nuet...</em></p><p><strong>Åbn dine øjne. Hvordan har du det?</strong></p><p><em>Dette er din nulstillingsknap. Brug den!</em></p><hr><h2 id="slide-13-værktøj-nr-2-din-rutine-før-optagelse-🎯" tabindex="-1">Slide 13: Værktøj nr. 2 - Din rutine før optagelse 🎯 <a class="header-anchor" href="#slide-13-værktøj-nr-2-din-rutine-før-optagelse-🎯" aria-label="Permalink to &quot;Slide 13: Værktøj nr. 2 - Din rutine før optagelse 🎯&quot;">​</a></h2><h3 id="opbyg-automatisk-konsistens" tabindex="-1">Opbyg automatisk konsistens <a class="header-anchor" href="#opbyg-automatisk-konsistens" aria-label="Permalink to &quot;Opbyg automatisk konsistens&quot;">​</a></h3><p><strong>4-trinsrutinen:</strong></p><p><strong>1️⃣ VISUALISER (3 sekunder)</strong> Se det perfekte billede for dig. Se det lande præcis der, hvor du ønsker.</p><p><strong>2️⃣ TRÆK ÅND (2 sekunder)</strong> En dyb indånding. Skift fra planlægnings- til udførelsestilstand.</p><p><strong>3️⃣ ANKER (2 sekunder)</strong> Rør ved din kugle. Føl vægten. Fysisk forbindelse.</p><p><strong>4️⃣ UDFØR (2 sekunder)</strong> Stol fuldstændigt på dig selv. Lad din krop gøre, hvad den ved.</p><p><strong>⏱️ I alt: 9 sekunder. Samme hver gang.</strong></p><h3 id="hvorfor-det-virker" tabindex="-1">Hvorfor det virker: <a class="header-anchor" href="#hvorfor-det-virker" aria-label="Permalink to &quot;Hvorfor det virker:&quot;">​</a></h3><p><strong>Konsistens = Tillid = Ydeevne</strong></p><hr><h2 id="slide-14-værktøj-3-protokol-til-fejlretning-🔄" tabindex="-1">Slide 14: Værktøj #3 - Protokol til fejlretning 🔄 <a class="header-anchor" href="#slide-14-værktøj-3-protokol-til-fejlretning-🔄" aria-label="Permalink to &quot;Slide 14: Værktøj #3 - Protokol til fejlretning 🔄&quot;">​</a></h2><h3 id="darlig-chance-her-er-din-4-trins-gendannelse" tabindex="-1">Dårlig chance? Her er din 4-trins gendannelse: <a class="header-anchor" href="#darlig-chance-her-er-din-4-trins-gendannelse" aria-label="Permalink to &quot;Dårlig chance? Her er din 4-trins gendannelse:&quot;">​</a></h3><p><strong>1️⃣ BEKRÆFT (2 sekunder)</strong> &quot;Det gik ikke som planlagt.&quot; (Ingen fordømmelse, kun fakta)</p><p><strong>2️⃣ SLIP (3 sekunder)</strong> Fysisk nulstilling: Ryst dine hænder, rul med skuldrene, gå 3 skridt.</p><p><strong>3️⃣ REFOKUSER (3 sekunder)</strong> &quot;Næste skud er en NY mulighed.&quot; (Ikke relateret til den sidste)</p><p><strong>4️⃣ UDFØR (Brug din rutine)</strong> Stol på din rutine før indsprøjtning. En frisk start.</p><h3 id="den-vigtigste-indsigt" tabindex="-1">Den vigtigste indsigt: <a class="header-anchor" href="#den-vigtigste-indsigt" aria-label="Permalink to &quot;Den vigtigste indsigt:&quot;">​</a></h3><p><strong>Hvert skud er uafhængigt. Overfør ikke fejl fremad.</strong></p><p><em>De bedste spillere har den korteste hukommelse for dårlige skud.</em></p><hr><h2 id="slide-15-ærlig-snak-hvad-stopper-dig-💬" tabindex="-1">Slide 15: ÆRLIG SNAK - Hvad stopper dig? 💬 <a class="header-anchor" href="#slide-15-ærlig-snak-hvad-stopper-dig-💬" aria-label="Permalink to &quot;Slide 15: ÆRLIG SNAK - Hvad stopper dig? 💬&quot;">​</a></h2><h3 id="gruppediskussion-5-minutter" tabindex="-1">Gruppediskussion (5 minutter) <a class="header-anchor" href="#gruppediskussion-5-minutter" aria-label="Permalink to &quot;Gruppediskussion (5 minutter)&quot;">​</a></h3><p><strong>Lad os høre fra dig:</strong></p><p><strong>Spørgsmål 1:</strong><em>&quot;Hvornår føler du dig MEST i flow? Hvilke forhold hjælper?&quot;</em></p><p><strong>Spørgsmål 2:</strong><em>&quot;Hvad er din største mentale udfordring i konkurrencer?&quot;</em></p><p><strong>Spørgsmål 3:</strong><em>&quot;Hvilket af disse værktøjer giver mest genklang hos dig?&quot;</em></p><ul><li>3-åndedrætsnulstilling</li><li>Rutine før optagelse</li><li>Indre coach-omformulering</li><li>Fejlretning</li></ul><p><strong>Del åbent - dette er et trygt rum!</strong></p><hr><h2 id="slide-16-din-handlingsplan-vælg-en-✅" tabindex="-1">Slide 16: Din handlingsplan - Vælg ÉN! ✅ <a class="header-anchor" href="#slide-16-din-handlingsplan-vælg-en-✅" aria-label="Permalink to &quot;Slide 16: Din handlingsplan - Vælg ÉN! ✅&quot;">​</a></h2><h3 id="denne-uges-udfordring" tabindex="-1">Denne uges udfordring: <a class="header-anchor" href="#denne-uges-udfordring" aria-label="Permalink to &quot;Denne uges udfordring:&quot;">​</a></h3><p><strong>Vælg KUN ÉN teknik at øve dig på:</strong></p><p><strong>Mulighed A: 🌬️ 3-Årdrætsnulstilling</strong> Brug efter HVER fejl i træningen</p><p><strong>Mulighed B: 🎯 Rutine før optagelse</strong> Samme 4-trins rutine på HVERT kast</p><p><strong>Mulighed C: 💬 Indre Coach</strong> Omformuler ÉN kritisk tanke pr. session</p><p><strong>Mulighed D: 🔄 Tilstandsskift</strong> Øvelsesplanlægning → udførelsesknap</p><h3 id="hvorfor-kun-en" tabindex="-1">Hvorfor kun én? <a class="header-anchor" href="#hvorfor-kun-en" aria-label="Permalink to &quot;Hvorfor kun én?&quot;">​</a></h3><p><strong>Bliv klogere på ét værktøj, før du tilføjer et andet.</strong><em>Dybde slår bredde i mental træning.</em></p><hr><h2 id="slide-17-følg-dine-fremskridt-📊" tabindex="-1">Slide 17: Følg dine fremskridt 📊 <a class="header-anchor" href="#slide-17-følg-dine-fremskridt-📊" aria-label="Permalink to &quot;Slide 17: Følg dine fremskridt 📊&quot;">​</a></h2><h3 id="hvad-skal-man-bemærke-i-denne-uge" tabindex="-1">Hvad skal man bemærke i denne uge: <a class="header-anchor" href="#hvad-skal-man-bemærke-i-denne-uge" aria-label="Permalink to &quot;Hvad skal man bemærke i denne uge:&quot;">​</a></h3><p><strong>🎯 Flow-øjeblikke:</strong></p><ul><li>Hvornår følte du dig &quot;i zonen&quot;?</li><li>Hvilken tid på dagen?</li><li>Hvilken type skud?</li><li>Hvad hjalp dig med at nå dertil?</li></ul><p><strong>💪 Teknik succes:</strong></p><ul><li>Hvilket værktøj virkede bedst?</li><li>Hvornår brugte du den?</li><li>Hvad blev resultatet?</li></ul><p><strong>📝 Før en simpel logbog:</strong><em>&quot;Brugte 3-åndedrætsnulstilling efter fejl → følte mig roligere → lavede næste skud&quot;</em></p><h3 id="malet" tabindex="-1">Målet: <a class="header-anchor" href="#malet" aria-label="Permalink to &quot;Målet:&quot;">​</a></h3><p><strong>Find DINE mønstre. Byg DIT system.</strong></p><hr><h2 id="slide-18-fortsæt-din-rejse-🚀" tabindex="-1">Slide 18: Fortsæt din rejse 🚀 <a class="header-anchor" href="#slide-18-fortsæt-din-rejse-🚀" aria-label="Permalink to &quot;Slide 18: Fortsæt din rejse 🚀&quot;">​</a></h2><h3 id="gratis-ressourcer-pa-carreau-app" tabindex="-1">Gratis ressourcer på carreau.app: <a class="header-anchor" href="#gratis-ressourcer-pa-carreau-app" aria-label="Permalink to &quot;Gratis ressourcer på carreau.app:&quot;">​</a></h3><p><strong>📚 Dybdegående undersøgelser:</strong></p><ul><li><strong>Zonen</strong> - Master flowtilstande</li><li><strong>Mental styrke</strong> - Avanceret preshåndtering</li><li><strong>Teamdynamik</strong> - Kommunikation og tillid</li><li><strong>Mindfulness</strong> - Fokus i nuet</li></ul><p><strong>🛠️ Praktiske værktøjer:</strong></p><ul><li><strong>Målskabelon</strong> - Strukturer din udvikling</li><li><strong>Skabelon til dagbog</strong> - Spor daglige fremskridt</li><li><strong>Workshopguide</strong> - Afhold dine egne sessioner</li></ul><p><strong>Alt gratis. Alt tilgængeligt. Alt designet til elitespillere.</strong></p><hr><h2 id="slide-19-de-4-store-ideer-💡" tabindex="-1">Slide 19: De 4 store idéer 💡 <a class="header-anchor" href="#slide-19-de-4-store-ideer-💡" aria-label="Permalink to &quot;Slide 19: De 4 store idéer 💡&quot;">​</a></h2><h3 id="tag-disse-med-hjem" tabindex="-1">Tag disse med hjem: <a class="header-anchor" href="#tag-disse-med-hjem" aria-label="Permalink to &quot;Tag disse med hjem:&quot;">​</a></h3><p><strong>1️⃣ Flow er en FÆRDIGHED, ikke held</strong> Du kan lære at få adgang til det efter behov</p><p><strong>2️⃣ Din indre stemme FORMER din præstation</strong> Træn dig selv, kritiser ikke dig selv</p><p><strong>3️⃣ Enkle værktøjer ARBEJDER under pres</strong> 3 åndedrag. En rutine. En nulstilling. Det er det.</p><p><strong>4️⃣ Øvelse gør varig</strong> Mentale færdigheder kræver træning ligesom tekniske færdigheder</p><h3 id="sandheden-1" tabindex="-1">Sandheden: <a class="header-anchor" href="#sandheden-1" aria-label="Permalink to &quot;Sandheden:&quot;">​</a></h3><p><strong>Mental træning er ikke mystisk. Det er praktisk.</strong></p><hr><h2 id="slide-20-spørgsmal-lad-os-snakke-💬" tabindex="-1">Slide 20: Spørgsmål? Lad os snakke! 💬 <a class="header-anchor" href="#slide-20-spørgsmal-lad-os-snakke-💬" aria-label="Permalink to &quot;Slide 20: Spørgsmål? Lad os snakke! 💬&quot;">​</a></h2><h1 id="aben-diskussion" tabindex="-1">Åben diskussion <a class="header-anchor" href="#aben-diskussion" aria-label="Permalink to &quot;Åben diskussion&quot;">​</a></h1><p><strong>Hvilke spørgsmål har du?</strong></p><p><strong>Hvilke oplevelser vil du dele?</strong></p><p><strong>Hvilke udfordringer står du over for?</strong></p><p><strong>Hvad vil du prøve først?</strong></p><p><em>Dette er DIN session. Lad os gøre den værdifuld for DIG.</em></p><hr><h2 id="slide-21-din-udfordring-🎯" tabindex="-1">Slide 21: Din udfordring 🎯 <a class="header-anchor" href="#slide-21-din-udfordring-🎯" aria-label="Permalink to &quot;Slide 21: Din udfordring 🎯&quot;">​</a></h2><h1 id="denne-uges-mission" tabindex="-1">Denne uges mission: <a class="header-anchor" href="#denne-uges-mission" aria-label="Permalink to &quot;Denne uges mission:&quot;">​</a></h1><p><strong>1️⃣ Vælg ET værktøj</strong> (3-åndedrætsnulstilling, rutine før skud, indre træner eller tilstandsskift)</p><p><strong>2️⃣ Øv det HVER session</strong> (Konsistens overgår intensitet)</p><p><strong>3️⃣ Bemærk hvilke ændringer</strong> (Spor dine fremskridt)</p><p><strong>4️⃣ Del dine resultater</strong> (Med dine træningspartnere eller på carreau.app)</p><h3 id="huske" tabindex="-1">Huske: <a class="header-anchor" href="#huske" aria-label="Permalink to &quot;Huske:&quot;">​</a></h3><p><strong>Små ændringer → Store resultater</strong></p><hr><h2 id="slide-22-tak-🙏" tabindex="-1">Slide 22: Tak! 🙏 <a class="header-anchor" href="#slide-22-tak-🙏" aria-label="Permalink to &quot;Slide 22: Tak! 🙏&quot;">​</a></h2><h1 id="du-har-styr-pa-det" tabindex="-1">Du har styr på det! <a class="header-anchor" href="#du-har-styr-pa-det" aria-label="Permalink to &quot;Du har styr på det!&quot;">​</a></h1><p><strong>Hvad du lærte i dag:</strong></p><ul><li>✅ Sådan får du adgang til flowtilstande</li><li>✅ Sådan håndterer du din indre kritiker</li><li>✅ Praktiske værktøjer, der fungerer under pres</li><li>✅ En klar handlingsplan for denne uge</li></ul><p><strong>Næste trin:</strong></p><ol><li>Vælg din ENE teknik</li><li>Øv det konsekvent</li><li>Besøg carreau.app for flere ressourcer</li><li>Del dine fremskridt med gruppen</li></ol><h3 id="rejsen-starter-nu" tabindex="-1">Rejsen starter nu: <a class="header-anchor" href="#rejsen-starter-nu" aria-label="Permalink to &quot;Rejsen starter nu:&quot;">​</a></h3><p><strong>Mental træning er praktisk, ikke mystisk.</strong><strong>Start i dag. Se resultater snart.</strong></p><hr><p><em>Pétanque Academy - Elite Player Development</em><em>carreau.app - Gratis ressourcer til elitespillere</em></p>',201)])])}]]);export{i as __pageData,a as default};
